/**
 * Keeps the mobsfscan hardening when `android/` is regenerated by `expo prebuild`:
 *  - no adb / cloud / device-transfer backup of patient data (allowBackup=false + extraction rules)
 *  - MainActivity launchMode=singleTop + taskAffinity="" (StrandHogg 1/2 task-hijacking; deep links still
 *    reach the running activity through onNewIntent)
 */
const fs = require('fs');
const path = require('path');
const { withAndroidManifest, withDangerousMod } = require('@expo/config-plugins');

const RULES = `<?xml version="1.0" encoding="utf-8"?>
<data-extraction-rules>
    <cloud-backup>
        <exclude domain="root" /><exclude domain="file" /><exclude domain="database" />
        <exclude domain="sharedpref" /><exclude domain="external" />
    </cloud-backup>
    <device-transfer>
        <exclude domain="root" /><exclude domain="file" /><exclude domain="database" />
        <exclude domain="sharedpref" /><exclude domain="external" />
    </device-transfer>
</data-extraction-rules>
`;

module.exports = function withAndroidSecurity(config) {
  config = withAndroidManifest(config, (cfg) => {
    const app = cfg.modResults.manifest.application?.[0];
    if (app) {
      app.$['android:allowBackup'] = 'false';
      app.$['android:fullBackupContent'] = 'false';
      app.$['android:dataExtractionRules'] = '@xml/data_extraction_rules';
      for (const activity of app.activity || []) {
        if (activity.$['android:name'] === '.MainActivity') {
          activity.$['android:launchMode'] = 'singleTop';
          activity.$['android:taskAffinity'] = '';
        }
      }
    }
    return cfg;
  });
  return withDangerousMod(config, [
    'android',
    async (cfg) => {
      const dir = path.join(cfg.modRequest.platformProjectRoot, 'app/src/main/res/xml');
      fs.mkdirSync(dir, { recursive: true });
      fs.writeFileSync(path.join(dir, 'data_extraction_rules.xml'), RULES);
      return cfg;
    },
  ]);
};
